// token, the veil <image>s in .ov-flt, the legend block and the cell-card row.
// The parsing, index and painting live in the Worker (ne_glyph_filter.js);
// this is wiring. Spliced into neGlyphScript (ne_glyph.go) before the test hook.
package main

// neGlyphFiltHTML — the chip row; appended to .glyph-side after the tools.
const neGlyphFiltHTML = `<div class="glyph-filt" hidden role="group" aria-label="filter"><span class="gf-chips" role="list"></span><span class="gf-add"><input type="text" class="gf-in" placeholder="add a condition" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" enterkeyhint="done" aria-label="add a filter condition" aria-autocomplete="list" aria-expanded="false"><ul class="gf-l" role="listbox" hidden></ul></span><span class="gf-n" aria-live="polite"></span><button type="button" class="gt-b gf-x" aria-label="clear the filter" title="clear the filter"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 4l8 8M12 4l-8 8"/></svg></button></div>`

// neGlyphFiltBtn — the funnel (lucide `funnel`), sits after the find box.
const neGlyphFiltBtn = `<button type="button" class="gt-b gt-flt" aria-pressed="false" aria-label="filter cells" title="filter · veil the cells that do not meet your conditions ( f )"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 20a1 1 0 0 0 .553.895l2 1A1 1 0 0 0 14 21v-7a2 2 0 0 1 .517-1.341L21.74 4.67A1 1 0 0 0 21 3H3a1 1 0 0 0-.742 1.67l7.225 7.989A2 2 0 0 1 10 14z"/></svg><span class="gt-t">filter</span></button>`

